// === Tab: mySketch ===
const sketch = (p) => {
    let H = 1024;
    let W = 1024;

    let min_width;
    let max_width;

    let G;

    let SEED;

    let A;
    let UPDATE_PARAM;
    let Z;
    let HR;
    let VT;

    //quadratic map
    p.setup = () => {
        p.createCanvas(p.windowWidth, p.windowHeight);
        G = p.createGraphics(W, H);

        min_width = p.min(p.width, p.height);
        max_width = p.max(p.width, p.height);

        SEED = p.random()*998244353;

        p.randomSeed(SEED);
        p.noiseSeed(SEED);


        BACK_COL = 10;
        UPDATE_PARAM = true;
        Z = 1.3;
        HR = 0;
        VT = 0;
        A = Array(12);
    };

    p.draw = () => {
        p.blendMode(p.BLEND);
        p.background(BACK_COL);

        G.colorMode(p.RGB);
        G.background(BACK_COL);

        G.strokeWeight(3);

        if(UPDATE_PARAM == true){
            for(let i=0;i<12;++i){
                A[i] = p.random(-1.2, 1.2);
            }
        }

        let x = .0;
        let y = .0;
        for(let i=0;i<10000;++i){
            let nx = A[0] + A[1]*x + A[2]*x*x + A[3]*x*y + A[4]*y + A[5]*y*y;
            let ny = A[6] + A[7]*x + A[8]*x*x + A[9]*x*y + A[10]*y + A[11]*y*y;

            G.stroke(255);
            G.point(
                p.map(nx, -Z+HR, Z+HR, 0, W),
                p.map(ny, -Z+VT, Z+VT, 0, H),
            );
            x = nx;
            y = ny;
        }

        let s = "";
        for(let i=0;i<12;++i){
            s += "a" + (i).toString() + " = " + A[i].toFixed(10) + "\n";
        }

        G.strokeWeight(1);
        G.fill(255);
        G.stroke(255);
        G.textSize(14);
        G.text(s, 10, 10, 180, 300);



        p.image(G, (p.width-min_width)/2, (p.height-min_width)/2, min_width, min_width, 0, 0, W, H);
        p.noLoop();
    };


    p.keyPressed = () => {
        if(p.key == 's') {
            G.save("image.png");
        }
        if(p.key == "z"){
            UPDATE_PARAM = true;
            Z = 1.3;
            VT = 0.
            HR = 0.
            p.loop();
        }
        if(p.key == "l"){
            UPDATE_PARAM = false;
            Z = p.max(0, Z+.1);
            p.loop();
        }
        if(p.key == "h"){
            UPDATE_PARAM = false;
            Z = p.max(0, Z-.1);
            p.loop();
        }
        if(p.keyCode == p.UP_ARROW){
            UPDATE_PARAM = false;
            VT = VT + .1;
            p.loop();
        }
        if(p.keyCode == p.DOWN_ARROW){
            UPDATE_PARAM = false;
            VT = VT -.1;
            p.loop();
        }
        if(p.keyCode == p.LEFT_ARROW){
            UPDATE_PARAM = false;
            HR = HR + .1;
            p.loop();
        }
        if(p.keyCode == p.RIGHT_ARROW){
            UPDATE_PARAM = false;
            HR = HR - .1;
            p.loop();
        }
    }


};

new p5(sketch);

